(()=>{
const select=document.querySelector('#compat-model');if(!select)return;
const start=document.querySelector('#compat-start');const results=document.querySelector('#compat-results');const visual=document.querySelector('#compat-visual');const progress=document.querySelector('#compat-progress');let data=null;let busy=false;
const el=(tag,className,text)=>{const item=document.createElement(tag);if(className)item.className=className;if(text)item.textContent=text;return item};
const svg=(name)=>{const node=document.createElementNS('http://www.w3.org/2000/svg','svg');node.classList.add('icon');node.setAttribute('aria-hidden','true');node.setAttribute('focusable','false');const use=document.createElementNS(node.namespaceURI,'use');use.setAttribute('href','assets/icons.svg#'+name);node.append(use);return node};
const badge=(state)=>{const node=el('span','hardware-badge '+state.level);node.append(svg(state.level==='critical'?'warning':state.level==='headroom'?'check':'info'),document.createTextNode(state.label));return node};
function sourceLink(label,url){const link=el('a','',label);link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.append(svg('arrow-up-right'));return link}
function card(label,value,note,iconName,state){const item=el('article','hardware-card '+(state?.level||'information'));const top=el('div','hardware-card-top');const name=el('span','hardware-label',label);top.append(svg(iconName),name);if(state)top.append(badge(state));item.append(top,el('h3','',value),el('p','',note));return item}
function render(model){const baseline=data.baseline;const memory=compatibilityRules.memory(model.ram,baseline.ramGB);const ios=compatibilityRules.entry(document.querySelector('#compat-ios').value,baseline.ios,'iOS');const storage=compatibilityRules.entry(document.querySelector('#compat-storage').value,baseline.freeStorageGB,'GB');const invalidIOS=document.querySelector('#compat-ios').validity.valid;const invalidStorage=document.querySelector('#compat-storage').validity.valid;if(!invalidIOS){ios.level='unknown';ios.label='Invalid entry';ios.value='Check your entry';ios.note='Use an iOS version between 1 and 99.'}if(!invalidStorage){storage.level='unknown';storage.label='Invalid entry';storage.value='Check your entry';storage.note='Use a valid non-negative storage value.'}
document.querySelector('#compat-result-title').textContent=model.name;const verdict=document.querySelector('#compat-verdict');verdict.className='compat-verdict '+memory.level;const verdictIcon=el('div','verdict-icon');verdictIcon.append(svg(memory.level==='critical'?'warning':memory.level==='headroom'?'check':'info'));const summary=el('div');let heading=memory.title;let note=memory.note;if([ios,storage].some(check=>check.level==='critical')){heading='One or more checker guidelines are not met';note='Review the highlighted checks below. More RAM does not override an unsupported iOS version or insufficient storage.';verdict.className='compat-verdict critical'}else if(memory.level==='headroom'&&ios.level==='headroom'&&storage.level==='headroom'){heading='Meets the reference checks';note='Installed RAM and the iOS and storage values you provided meet the checker baseline. This is not a game test or certification.'}summary.append(el('h3','',heading),el('p','',note));verdict.replaceChildren(verdictIcon,summary);
document.querySelector('#memory-support').hidden=memory.level!=='critical';
const grid=document.querySelector('#hardware-grid');grid.replaceChildren(card('System on chip',model.chip||'Unverified','Apple silicon model. CPU, GPU, and Neural Engine are integrated into this chip.','cpu'),card('CPU',model.cpu?model.cpu+' cores':'Unverified','Central processing unit. Core counts are hardware specifications, not performance scores.','cpu'),card('GPU',model.gpu?model.gpu+' cores':'Unverified','Graphics processing unit. Rendering performance also depends on the port and its settings.','layers'),card('Installed RAM',model.ram!==null?model.ram+' GB':'Unverified',memory.note,'memory',memory),card('Neural Engine',model.neural||'Unverified','Machine-learning hardware. Its presence is not a GTA V compatibility requirement.','cpu'),card('Assessment type','Model profile','Source-based hardware lookup. No live RAM, temperature, or performance measurement.','info'));
const runtime=document.querySelector('#runtime-grid');runtime.replaceChildren(card('Installed iOS',ios.value,ios.note,'gamepad',ios),card('Free storage',storage.value,storage.note,'storage',storage));const links=document.querySelector('#compat-source-links');links.replaceChildren(sourceLink('Apple: hardware specifications',model.appleSource));if(model.ramSource){const source=data.sources[model.ramSource];links.append(sourceLink(source.label,source.url))}else links.append(el('p','source-unknown','RAM source: not yet verified for this model.'));const reference=data.sources[baseline.source];links.append(sourceLink(reference.label,reference.url),el('p','source-review','Sources reviewed '+data.reviewed+'. '+baseline.note));results.hidden=false;results.querySelectorAll('.hardware-card').forEach((item,index)=>item.style.setProperty('--card-delay',index*45+'ms'));document.querySelector('#chip-preview').textContent=model.chip||'UNVERIFIED';document.querySelector('#compat-visual-title').textContent='Profile ready.';progress.textContent='Review the hardware and highlighted checks below.';document.querySelector('#compat-result-title').focus();results.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
start.addEventListener('click',async()=>{if(!data||!select.value||busy)return;const model=data.models.find(item=>item.id===select.value);if(!model)return;busy=true;start.disabled=true;select.disabled=true;start.firstChild.textContent='Reviewing ';visual.classList.add('reviewing');visual.setAttribute('aria-busy','true');results.hidden=true;const labels=['Reading the hardware profile…','Comparing installed memory…','Preparing requirement checks…'];const delay=matchMedia('(prefers-reduced-motion: reduce)').matches?0:400;try{for(const label of labels){progress.textContent=label;if(delay)await new Promise(resolve=>setTimeout(resolve,delay))}render(model)}finally{busy=false;start.disabled=false;select.disabled=false;start.firstChild.textContent='Check again ';visual.classList.remove('reviewing');visual.removeAttribute('aria-busy')}});
select.addEventListener('change',()=>{results.hidden=true;document.querySelector('#compat-visual-title').textContent='Ready to review.';progress.textContent='Press Start to review the selected model.';start.firstChild.textContent='Start ';start.disabled=!select.value;try{window.sitePrivacy?.setPreference('gtav-compatibility-model',select.value)}catch{}});
document.querySelectorAll('#compat-ios,#compat-storage').forEach(input=>input.addEventListener('input',()=>{if(!results.hidden){results.hidden=true;progress.textContent='Details changed. Press Check again to update the results.'}}));
document.querySelector('#compat-change').addEventListener('click',()=>{select.focus();select.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})});
async function init(){try{const response=await fetch('compatibility-data.json',{cache:'no-cache'});if(!response.ok)throw Error('Could not load device profiles.');data=await response.json();select.replaceChildren(el('option','','Select your iPhone'));select.firstChild.value='';const groups=new Map();data.models.forEach(model=>{if(!groups.has(model.family)){const group=el('optgroup');group.label=model.family==='X / XS / XR'?'iPhone X / XS / XR':model.family==='17 / Air'?'iPhone 17 / Air':'iPhone '+model.family+' series';groups.set(model.family,group);select.append(group)}const option=el('option','',model.name);option.value=model.id;groups.get(model.family).append(option)});let saved='';try{saved=window.sitePrivacy?.getPreference('gtav-compatibility-model')||'';if(!saved){const onboarding=JSON.parse(localStorage.getItem('gtav-community-onboarding')||'null');saved=data.models.find(item=>item.name===onboarding?.model)?.id||''}}catch{}if(data.models.some(model=>model.id===saved)){select.value=saved;start.disabled=false}select.disabled=false}catch(error){select.replaceChildren(el('option','','Profiles unavailable'));const message=document.querySelector('#compat-error');message.textContent='Device profiles could not be loaded. Please refresh and try again.';message.hidden=false}}
init();
})();
